glsl3.frag:
precision highp float;
uniform CCGlobal {
  mat4 cc_matView;
  mat4 cc_matViewInv;
  mat4 cc_matProj;
  mat4 cc_matProjInv;
  mat4 cc_matViewProj;
  mat4 cc_matViewProjInv;
  vec4 cc_cameraPos;
  vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_screenScale;
};
in vec4 v_color;
#if USE_TEXTURE
  in vec2 v_uv0;
  uniform sampler2D texture;
#endif
uniform HologramLoading {
  vec4 energyColor;
  vec4 highlightColor;
  vec4 blockColorA;
  vec4 blockColorB;
  vec4 blockColorC;
  vec4 uvRect;
  vec2 blockGrid;
  float progress;
  float scanWidth;
  float scanIntensity;
  float blockSpeed;
  float blockIntensity;
  float blockRange;
  float fieldIntensity;
  float columnWidth;
  float rayDensity;
  float raySpeed;
  float glitchStrength;
  float glitchRate;
  float edgeFade;
  float endFadeStart;
  float flipY;
};
float hash12(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}
vec3 getDataColor(float key) {
  vec3 color = blockColorA.rgb;
  color = mix(color, blockColorB.rgb, step(0.46, key));
  color = mix(color, blockColorC.rgb, step(0.74, key));
  color = mix(color, highlightColor.rgb, step(0.9, key));
  return color;
}
